# Generated by ROS 2 Humble Setup

$ErrorActionPreference = 'Stop'

function Assert-Installation([string] $Root) {
    $item = [IO.DirectoryInfo]::new($Root)
    if (!$item.Exists -or !$item.Parent -or $item.Root.FullName.StartsWith('\\')) {
        throw 'Open the uninstaller from its local ROS 2 installation folder.'
    }
    while ($item) {
        if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) {
            throw "The uninstall path contains a junction or symbolic link: $($item.FullName)"
        }
        $item = $item.Parent
    }

    $marker = [IO.FileInfo]::new((Join-Path $Root '.ros2-release'))
    if (!$marker.Exists -or ($marker.Attributes -band [IO.FileAttributes]::ReparsePoint) -or
        [IO.File]::ReadAllText($marker.FullName) -ne '@ROS_RELEASE@') {
        throw "The ROS 2 Humble installation marker is missing or invalid in $Root."
    }
}

function Remove-RosShortcut($Shell, [Environment+SpecialFolder] $Folder, [string] $Name, [string] $Launcher) {
    $directory = [Environment]::GetFolderPath($Folder)
    if (!$directory) { return }
    $path = Join-Path $directory "$Name.lnk"
    if (![IO.File]::Exists($path)) { return }

    $shortcut = $Shell.CreateShortcut($path)
    $cmd = Join-Path ([Environment]::SystemDirectory) 'cmd.exe'
    $arguments = '/d /v:off /s /k ""' + $Launcher + '""'
    if ($shortcut.TargetPath -eq $cmd -and $shortcut.Arguments -eq $arguments) {
        [IO.File]::Delete($path)
    }
}

function Wait-RosProcesses([string] $Root, [string[]] $Processes) {
    $form = New-Object System.Windows.Forms.Form
    $form.Text = 'Uninstall ROS 2 Humble'
    $form.StartPosition = 'CenterScreen'
    $form.FormBorderStyle = 'FixedDialog'
    $form.AutoScaleMode = 'Font'
    $form.MinimizeBox = $false
    $form.MaximizeBox = $false
    $form.ClientSize = [System.Drawing.Size]::new(510, 250)

    $label = New-Object System.Windows.Forms.Label
    $label.SetBounds(14, 14, 482, 52)
    $label.Text = 'Close these ROS command prompts and receiver processes. Uninstall will continue automatically once they exit.'
    $list = New-Object System.Windows.Forms.ListBox
    $list.SetBounds(14, 70, 482, 126)
    $list.Items.AddRange([object[]] $Processes)
    $cancel = New-Object System.Windows.Forms.Button
    $cancel.SetBounds(396, 207, 100, 30)
    $cancel.Text = 'Cancel'
    $cancel.DialogResult = 'Cancel'
    $form.CancelButton = $cancel
    $form.Controls.AddRange(@($label, $list, $cancel))

    $scan = ${function:Get-RosProcesses}
    $timer = New-Object System.Windows.Forms.Timer
    $timer.Interval = 1000
    $timer.add_Tick({
        try {
            $active = @(& $scan $Root)
            if ($active.Count -eq 0) { $form.DialogResult = 'OK' }
            else {
                $list.Items.Clear()
                $list.Items.AddRange([object[]] $active)
            }
        }
        catch {
            $form.Tag = $_
            $form.DialogResult = 'Abort'
        }
    }.GetNewClosure())
    try {
        $timer.Start()
        $result = $form.ShowDialog()
        if ($form.Tag) { throw $form.Tag }
        return $result -eq [System.Windows.Forms.DialogResult]::OK
    }
    finally {
        $timer.Dispose()
        $form.Dispose()
    }
}

function Invoke-RosUninstall([string] $InstallationPath, [scriptblock] $Confirm, [scriptblock] $WaitForClose = ${function:Wait-RosProcesses}) {
    $root = [IO.Path]::GetFullPath($InstallationPath)
    Assert-Installation $root
    if (!(& $Confirm $root)) { return $false }

    $sha = [Security.Cryptography.SHA256]::Create()
    try {
        $hash = [BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($root.ToUpperInvariant()))).Replace('-', '')
    }
    finally { $sha.Dispose() }
    $lock = Join-Path ([IO.Path]::GetTempPath()) "ros2-setup-$hash.lock"
    $lease = [IO.FileStream]::new($lock, [IO.FileMode]::OpenOrCreate, [IO.FileAccess]::ReadWrite,
        [IO.FileShare]::None, 1, [IO.FileOptions]::DeleteOnClose)
    try {
        Assert-Installation $root
        . (Join-Path $root 'ros-shells.ps1')
        $active = @(Get-RosProcesses $root)
        while ($active.Count -gt 0) {
            if (!(& $WaitForClose $root $active)) { return $false }
            $active = @(Get-RosProcesses $root)
        }

        $shell = New-Object -ComObject WScript.Shell
        Set-Location -LiteralPath ([IO.Path]::GetTempPath())
        [Environment]::CurrentDirectory = [IO.Path]::GetTempPath()

        # Keep the launchers and marker available if removal stops on an in-use file.
        $uninstallerFiles = @('.ros2-release', 'Uninstall ROS 2 Humble.cmd', 'uninstall-ros-humble.ps1', 'ros-shells.ps1')
        foreach ($entry in [IO.DirectoryInfo]::new($root).GetFileSystemInfos()) {
            if ($entry.Name -in $uninstallerFiles) { continue }
            if ($entry -is [IO.DirectoryInfo]) {
                # Directory.Delete on Windows removes nested reparse points without traversing their targets.
                $recursive = !($entry.Attributes -band [IO.FileAttributes]::ReparsePoint)
                $entry.Delete($recursive)
            }
            else { $entry.Delete() }
        }

        $rosLauncher = Join-Path $root 'ros-humble.cmd'
        $receiverLauncher = Join-Path $root 'pointcloud_receiver\start-receiver.cmd'
        Remove-RosShortcut $shell 'Programs' 'ROS 2 Humble Command Prompt' $rosLauncher
        Remove-RosShortcut $shell 'DesktopDirectory' 'ROS 2 Humble Command Prompt' $rosLauncher
        Remove-RosShortcut $shell 'DesktopDirectory' 'Start Point Cloud Receiver' $receiverLauncher

        foreach ($name in $uninstallerFiles) { [IO.File]::Delete((Join-Path $root $name)) }
        [IO.Directory]::Delete($root, $false)
        return $true
    }
    finally { $lease.Dispose() }
}

# Allow the container test to load the removal logic without opening desktop UI.
if ($MyInvocation.InvocationName -eq '.') { return }

Add-Type -AssemblyName System.Windows.Forms
try {
    $null = Invoke-RosUninstall $PSScriptRoot {
        param([string] $Root)
        $message = "This will remove your ROS 2 installation and all associated workspaces at:`r`n`r`n$Root`r`n`r`n" +
            "This includes the WalkableOR configuration and any files in that folder.`r`n`r`nAre you sure you want to continue?"
        $choice = [System.Windows.Forms.MessageBox]::Show($message, 'Uninstall ROS 2 Humble',
            'YesNo', 'Warning', 'Button2')
        return $choice -eq [System.Windows.Forms.DialogResult]::Yes
    }
}
catch {
    $null = [System.Windows.Forms.MessageBox]::Show("Uninstall stopped. $($_.Exception.Message)`r`n`r`nClose programs using the folder and try again.",
        'Uninstall ROS 2 Humble', 'OK', 'Error')
    exit 1
}
